// Health-record status, severity and provider have no backend columns yet, so they travel as a
// labelled first line of the summary. This module is the only place that writes or reads that line.
export type RecordSummaryMeta = {
  status: string
  severity: string
  doctor: string
  cleanSummary: string
}

export const RECORD_STATUSES = ['Active', 'Resolved', 'Inactive', 'Chronic'] as const
export const RECORD_SEVERITIES = ['Mild', 'Moderate', 'Severe'] as const

const META_PART = /^(Status|Severity|Doctor|Provider):\s*(.+)$/i

function cleanValue(value: string): string {
  return value.replace(/[·\r\n]+/g, ' ').replace(/\s+/g, ' ').trim()
}

export function formatRecordSummary(meta: Partial<RecordSummaryMeta>): string {
  const parts: string[] = []
  const status = cleanValue(meta.status ?? '')
  const severity = cleanValue(meta.severity ?? '')
  const doctor = cleanValue(meta.doctor ?? '')
  if (status) parts.push(`Status: ${status}`)
  if (severity) parts.push(`Severity: ${severity}`)
  if (doctor) parts.push(`Doctor: ${doctor}`)
  const text = (meta.cleanSummary ?? '').trim()
  return [parts.join(' · '), text].filter(Boolean).join('\n')
}

/** Only a first line made up entirely of labelled parts counts as metadata; free text is never rewritten. */
export function parseRecordSummary(summary?: string | null): RecordSummaryMeta {
  const empty = { status: '', severity: '', doctor: '', cleanSummary: (summary ?? '').trim() }
  if (!summary) return empty
  const [firstLine, ...rest] = summary.split('\n')
  const parts = firstLine.split('·').map((part) => part.trim())
  const matches = parts.map((part) => META_PART.exec(part))
  if (matches.some((match) => match === null)) return empty

  const meta: RecordSummaryMeta = { status: '', severity: '', doctor: '', cleanSummary: rest.join('\n').trim() }
  for (const match of matches) {
    const key = match![1].toLowerCase()
    const value = match![2].trim()
    if (key === 'status') meta.status = value
    else if (key === 'severity') meta.severity = value
    else meta.doctor = value
  }
  return meta
}

/** Local calendar date as YYYY-MM-DD. toISOString() is UTC and is a day behind before 05:30 in Sri Lanka. */
export function todayLocalDate(now: Date = new Date()): string {
  const month = String(now.getMonth() + 1).padStart(2, '0')
  const day = String(now.getDate()).padStart(2, '0')
  return `${now.getFullYear()}-${month}-${day}`
}
